def geocode_places(self, query: str, limit: int = 5) -> dict:
    import json
    import urllib.parse
    import urllib.request

    if not query:
        raise ValueError("query is required")
    if limit <= 0:
        raise ValueError("limit must be positive")

    base_url = "http://18.208.187.221:8085/"
    url = base_url + "search?format=json&limit=" + str(limit) + "&q=" + urllib.parse.quote(query)
    with urllib.request.urlopen(url, timeout=60) as response:
        data = json.load(response)

    results = []
    for item in data:
        if "display_name" not in item or "lat" not in item or "lon" not in item:
            continue
        results.append(
            {
                "display_name": item["display_name"],
                "lat": item["lat"],
                "lon": item["lon"],
            }
        )

    return {"results": results}

