def get_osrm_route(self, coordinates: list, service_port: int = 5000, overview: bool = False, steps: bool = True) -> dict:
    import json
    import urllib.request

    if not coordinates or len(coordinates) < 2:
        raise ValueError("coordinates must contain at least two waypoints")
    if not service_port:
        raise ValueError("service_port is required")

    coord_parts = []
    for coordinate in coordinates:
        lon = coordinate.get("lon")
        lat = coordinate.get("lat")
        if lon is None or lat is None:
            raise ValueError("each coordinate must include lon and lat")
        coord_parts.append(f"{lon},{lat}")

    overview_value = "true" if overview else "false"
    steps_value = "true" if steps else "false"
    url = (
        f"http://18.208.187.221:{service_port}/route/v1/driving/"
        + ";".join(coord_parts)
        + f"?overview={overview_value}&steps={steps_value}"
    )

    with urllib.request.urlopen(url, timeout=60) as response:
        data = json.load(response)

    if data.get("code") != "Ok":
        raise RuntimeError(f"OSRM route failed: {data}")

    route = data["routes"][0]
    legs = []
    for leg in route.get("legs", []):
        leg_record = {}
        if "duration" in leg:
            leg_record["duration"] = leg["duration"]
        if "distance" in leg:
            leg_record["distance"] = leg["distance"]
        legs.append(leg_record)

    return {
        "duration": route["duration"],
        "distance": route["distance"],
        "legs": legs,
    }
